jobs:
  terraform-plan:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Code
        uses: actions/checkout@v4

      - name: Setup Terraform
        uses: hashicorp/setup-terraform@v3

      - name: Setup Terraform Plan
        id: plan
        run: |
          terraform init
          terraform plan -out=tfplan.binary
          terraform show -no-color tfplan.binary > tfplan.txt

          # Process the plan to handle "open" change actions
          sed -i 's/^\s*open\s*$/change/g' tfplan.txt
          sed -i 's/^\s*open\s*$/change/g' tfplan.txt

          echo "plan_content<<EOF" >> $GITHUB_ENV
          cat tfplan.txt >> $GITHUB_ENV
          echo "EOF" >> $GITHUB_ENV

      - name: Comment on PR
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const planContent = fs.readFileSync('tfplan.txt', 'utf8');

            // Parse the plan content to extract changes
            const lines = planContent.split('\n');
            let changes = [];

            for (let i = 0; i < lines.length; i++) {
              const line = lines[i].trim();

              // Handle "open" change actions by converting them to "change"
              if (line.includes('open') && !line.includes('open in')) {
                const modifiedLine = line.replace(/open/g, 'change');
                changes.push(modifiedLine);
              } else if (line.startsWith('-') || line.startsWith('+') || line.startsWith('~')) {
                changes.push(line);
              } else if (line.startsWith('Plan:') || line.startsWith('Warning:') || line.startsWith('Error:')) {
                changes.push(line);
              }
            }

            const commentBody = `
### Terraform Plan Summary

\`\`\`hcl
${changes.join('\n')}
\`\`\`
            `;

            // Post comment to PR
            github.rest.issues.createComment({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: commentBody
            })
